data.xinshengCustomCss:
@import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600&display=swap');

.xt-root {
  --xt-bg: #ffffff;
  --xt-text: #2a3a4a;
  --xt-text-sub: #5a7a8a;
  --xt-text-muted: #8aa0b0;
  --xt-accent: #a0c4d8;
  --xt-accent-bg: #e6f0f5;
  --xt-border: #d8e4ec;
  --xt-radius: 12px;
  --xt-font: 'Inter', -apple-system, 'PingFang SC', sans-serif;
  padding: 18px 16px;
  background: #ffffff;
}

/* ===== 整体装饰 ===== */
.xt-root::before {
  content: "✦ ✦ ✦";
  position: absolute;
  top: 8px;
  right: 16px;
  font-size: 12px;
  color: #a0c4d8;
  letter-spacing: 4px;
}

/* ===== 头部 ===== */
.xt-header {
  margin-bottom: 20px;
  padding-bottom: 16px;
  border-bottom: 1px solid #e0ecf2;
  position: relative;
}

.xt-header::after {
  content: "●";
  position: absolute;
  bottom: -6px;
  left: -1px;
  font-size: 10px;
  color: #a0c4d8;
}

.xt-avatar {
  width: 48px;
  height: 48px;
  border-radius: 48px;
  border: 2px solid #c8dce8;
  padding: 1px;
}

.xt-name {
  font-size: 18px;
  font-weight: 600;
  color: #2a3a4a;
}

/* ===== 区块标题 ===== */
.xt-section-title {
  font-size: 12px;
  font-weight: 600;
  color: #7a9aac;
  letter-spacing: 1px;
  text-transform: uppercase;
  margin-top: 0;
  margin-bottom: 10px;
  position: relative;
  display: inline-block;
}

.xt-section-title::after {
  content: "";
  position: absolute;
  bottom: -2px;
  left: 0;
  width: 20px;
  height: 2px;
  background: #a0c4d8;
}

/* ===== 分隔线 ===== */
.xt-divider {
  height: 1px;
  background: linear-gradient(90deg, transparent, #d8e4ec, transparent);
  margin: 24px 0 16px;
  display: block;
  clear: both;
}

/* ===== 1. 心声 · 表里（左右网格）===== */
.xt-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 10px;
  margin-bottom: 0;
}

/* 左边 - 心声（白底） */
.xt-grid-stat:first-child {
  background: #ffffff !important;
  border: 1px solid #e0ecf2 !important;
  border-radius: 12px !important;
  padding: 14px 10px !important;
  box-shadow: 0 2px 6px rgba(160, 196, 216, 0.06);
  border-left: 4px solid #a0c4d8 !important;
}

.xt-grid-stat:first-child .xt-grid-stat-value {
  color: #2a3a4a !important;
  font-size: 14px !important;
  font-weight: 400 !important;
  line-height: 1.5 !important;
  font-style: normal !important;
}

.xt-grid-stat:first-child .xt-grid-stat-label {
  color: #7a9aac !important;
  font-size: 10px !important;
  font-weight: 600 !important;
  text-transform: uppercase !important;
  letter-spacing: 0.5px !important;
}

/* 右边 - 坏心思（浅蓝底） */
.xt-grid-stat:last-child {
  background: #e6f0f5 !important;
  border: none !important;
  border-radius: 12px !important;
  padding: 14px 10px !important;
  box-shadow: 0 2px 8px rgba(160, 196, 216, 0.1);
  border-left: 4px solid #8ab8d0 !important;
}

.xt-grid-stat:last-child .xt-grid-stat-value {
  color: #3a5a6a !important;
  font-size: 14px !important;
  font-weight: 400 !important;
  line-height: 1.5 !important;
  font-style: italic !important;
}

.xt-grid-stat:last-child .xt-grid-stat-label {
  color: #6a8a9a !important;
  font-size: 10px !important;
  font-weight: 600 !important;
  text-transform: uppercase !important;
  letter-spacing: 0.5px !important;
}

/* ===== 2. 随笔 ===== */
.xt-section:first-of-type .xt-section-body {
  display: none;
}

.xt-section:first-of-type .xt-section-title {
  display: inline-block !important;
  margin-bottom: 10px !important;
}

.xt-section:first-of-type .xt-text {
  display: block !important;
  background: #ffffff !important;
  border: none !important;
  border-left: 4px solid #a0c4d8 !important;
  border-radius: 12px !important;
  color: #2a3a4a !important;
  padding: 14px 16px 14px 20px !important;
  font-size: 15px;
  line-height: 1.8;
  box-shadow: 0 2px 6px rgba(160, 196, 216, 0.06);
  margin: 0 !important;
}
.xt-section:first-of-type .xt-text::before {
  display: none !important;
}

/* ===== 3. 备忘录 ===== */
.xt-list {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.xt-list-item {
  padding: 12px 14px;
  background: #ffffff;
  border: 1px solid #e0ecf2;
  border-radius: 10px;
  font-size: 14px;
  color: #2a3a4a;
}

.xt-list-item::before {
  content: "○";
  color: #a0c4d8;
  margin-right: 10px;
  font-size: 12px;
}

.xt-list-item-on {
  background: #f0f6fa;
  color: #8aa0b0;
  text-decoration: line-through;
}

.xt-list-item-on::before {
  content: "●";
  color: #7ab0c8;
}

/* ===== 4-5. 搜索记录 ===== */
.xt-section:nth-of-type(2) .xt-section-body,
.xt-section:nth-of-type(3) .xt-section-body {
  font-weight: 600;
  background: #e6f0f5;
  color: #3a5a6a;
  padding: 12px 14px;
  margin-bottom: 0;
  border: 1px solid #e0ecf2;
  border-bottom: none;
  border-radius: 12px 12px 0 0;
  font-size: 15px;
}

.xt-text {
  font-size: 14px;
  color: #5a7a8a;
  padding: 12px 14px 14px 28px;
  background: #ffffff;
  border: 1px solid #e0ecf2;
  border-top: none;
  border-radius: 0 0 12px 12px;
  margin-bottom: 10px;
  position: relative;
}

.xt-text::before {
  content: "";
  position: absolute;
  left: 14px;
  top: 14px;
  bottom: 14px;
  width: 4px;
  background: #a0c4d8;
  border-radius: 2px;
}

.xt-section:nth-of-type(2) .xt-section-title::before {
  content: "🔍";
  margin-right: 6px;
  font-size: 12px;
}

/* ===== 6. 聊天记录 ===== */
.xt-section:nth-of-type(4) .xt-text:first-of-type {
  font-size: 13px;
  font-weight: 500;
  color: #5a7a8a;
  padding: 0 0 8px 0;
  margin: 0;
  background: transparent;
  border: none;
}
.xt-section:nth-of-type(4) .xt-text:first-of-type::before {
  display: none;
}

.xt-bubbles {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.xt-bubble-left,
.xt-bubble-right {
  max-width: 70%;
  padding: 8px 12px;
  font-size: 13px;
  line-height: 1.4;
  border-radius: 16px;
}

.xt-bubble-left {
  align-self: flex-start;
  background: #e6f0f5;
  color: #3a5a6a;
  border-bottom-left-radius: 4px;
}

.xt-bubble-right {
  align-self: flex-end;
  background: #c8dce8;
  color: #2a4a5a;
  border-bottom-right-radius: 4px;
}

.xt-bubble-body {
  background: transparent !important;
  color: inherit;
}

/* ===== 7. 匿名提问 ===== */
.xt-section:nth-of-type(5) .xt-section-body {
  display: none;
}

.xt-section:nth-of-type(5) .xt-bubble-left {
  background: #d8e8f0;
  color: #3a5a6a;
}

.xt-section:nth-of-type(5) .xt-bubble-left .xt-bubble-body::before {
  content: "🎭 匿名";
  display: block;
  font-size: 9px;
  font-weight: 600;
  color: #7a9aac;
  margin-bottom: 4px;
}

.xt-section:nth-of-type(5) .xt-bubble-right .xt-bubble-body::before {
  content: "我";
  display: block;
  font-size: 9px;
  font-weight: 600;
  color: #7a9aac;
  margin-bottom: 4px;
}

/* ===== 8. 论坛求助 ===== */
.xt-section:nth-of-type(6) .xt-section-body {
  display: none;
}

.xt-section:nth-of-type(6) .xt-text:nth-of-type(1) {
  background: #ffffff;
  border-left: 4px solid #a0c4d8;
  border-radius: 0 12px 12px 0;
  padding: 12px 14px;
  margin: 0 0 12px 0;
  font-size: 14px;
  color: #2a3a4a;
  box-shadow: 0 1px 3px rgba(160, 196, 216, 0.04);
}
.xt-section:nth-of-type(6) .xt-text:nth-of-type(1)::before {
  display: none;
}

.xt-section:nth-of-type(6) .xt-text:nth-of-type(2) {
  background: #f4f8fb;
  border-left: 4px solid #b8d4e4;
  border-radius: 0 12px 12px 0;
  padding: 12px 14px;
  margin: 0 0 12px 0;
  font-size: 14px;
  color: #5a7a8a;
}
.xt-section:nth-of-type(6) .xt-text:nth-of-type(2)::before {
  display: none;
}

.xt-section:nth-of-type(6) .xt-text:nth-of-type(3) {
  background: #f4f8fb;
  border-left: 4px solid #b8d4e4;
  border-radius: 0 12px 12px 0;
  padding: 12px 14px;
  margin: 0 0 12px 0;
  font-size: 14px;
  color: #5a7a8a;
}
.xt-section:nth-of-type(6) .xt-text:nth-of-type(3)::before {
  display: none;
}

.xt-section:nth-of-type(6) .xt-text:nth-of-type(4) {
  background: #ffffff;
  border: 1px solid #a0c4d8;
  border-radius: 12px;
  padding: 12px 14px;
  margin: 16px 0 0 0;
  font-size: 14px;
  color: #2a3a4a;
  font-weight: 500;
}
.xt-section:nth-of-type(6) .xt-text:nth-of-type(4)::before {
  display: none;
}

/* ===== 9. 最近在干嘛 ===== */
.xt-section:nth-of-type(7) .xt-section-body {
  background: #e6f0f5;
  border: 1px solid #e0ecf2;
  color: #3a5a6a;
  font-weight: 500;
  text-align: center;
  padding: 14px 16px;
  border-radius: 14px;
  font-size: 16px;
}

.xt-section:nth-of-type(7) .xt-text {
  background: #ffffff;
  border: 1px solid #e0ecf2;
  border-radius: 12px;
  padding: 12px 14px;
  margin-top: 8px;
}

.xt-section:nth-of-type(7) .xt-section-title::before {
  content: "·";
  margin-right: 6px;
  font-size: 14px;
  color: #a0c4d8;
}

/* ===== 底部 ===== */
.xt-footer {
  margin-top: 24px;
  padding-top: 16px;
  text-align: center;
  font-size: 10px;
  color: #8aa0b0;
  letter-spacing: 2px;
  text-transform: uppercase;
  border-top: 1px solid #e0ecf2;
  position: relative;
}

.xt-footer::before {
  content: "✦";
  position: absolute;
  top: -6px;
  left: 50%;
  transform: translateX(-50%);
  font-size: 10px;
  color: #a0c4d8;
  background: #ffffff;
  padding: 0 8px;
}

/* ===== 间距 ===== */
.xt-spacer {
  height: 4px;
}

data.xinshengLayout:
# 八合一状态卡

@header charImage charName

# --- 1. 心声 · 表里 ---
@grid 2
  surfaceThought:stat "🤍 表面"
  secretThought:stat "🩵 真心"

@divider

# --- 2. 随笔 ---
@section 随笔
@text essayContent

@divider

# --- 3. 备忘录 ---
@section 备忘录
@list
  memo1
  memo2
  memo3

@divider

# --- 4. 搜索记录1 ---
@section 搜索记录
  search1
@text search1Thought

@spacer 8

# --- 5. 搜索记录2 ---
@section 
  search2
@text search2Thought

@divider


# --- 6. 聊天记录 ---
@section 聊天记录
@text chatTitle
@bubbles
  npcMsg1:left
  myMsg1:right
  npcMsg2:left
  myMsg2:right
  npcMsg3:left

@divider

# --- 7. 匿名提问 ---
@section 匿名提问
@bubbles
  anonymousQuestion:left
  myReply:right

@divider

# --- 8. 论坛求助 ---
@section 论坛求助
@text myPost
@text reply1
@text reply2
@text myReplyToNetizen

@divider

# --- 9. 最近在干嘛 ---
@section 最近在干嘛
  repoItem
@text repoDetail

@footer 状态手札
